/// An icon element. Rune's [`rune::icon`] takes a reference and a size; this is the catalog's
/// spelling so shell modules read `icons::icon(&icons::FOLDER, 16.0)`.
pub fn icon(i: &'static Icon, size: f32) -> rune::El {
    rune::icon(i, size)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_has_a_body_and_a_view_box() {
        assert_eq!(ALL.len(), 77);
        for icon in ALL {
            assert!(!icon.name.is_empty());
            assert!(icon.view > 0.0, "{}", icon.name);
            assert!(icon.body.contains('<'), "{}", icon.name);
            assert!(
                !icon.body.contains("<svg"),
                "{} kept its outer <svg> tag",
                icon.name
            );
        }
    }

    #[test]
    fn every_icon_draws_ink() {
        for icon in ALL {
            let coverage = rune::text::icon_coverage(icon, 32);
            assert!(
                coverage.iter().any(|&ink| ink > 0),
                "{} rasterizes to nothing",
                icon.name
            );
        }
    }

    #[test]
    fn the_shell_glyphs_are_present() {
        for icon in [
            &FOLDER,
            &PLUS,
            &CLOSE,
            &ARROW_LEFT,
            &ARROW_RIGHT,
            &SIDEBAR_MINIMALISTIC_LEFT,
            &HEARTH_LOGO,
            &TERMINAL,
            &SPLIT_COLUMNS,
            &GIT_BRANCH,
            &WIFI_OFF,
        ] {
            assert!(!icon.name.is_empty());
        }
    }
}
